                    "type": "text",
                    "value": " **类固醇**具有特定的环状结构。最重要的动物类固醇是**胆固醇**，它稳定细胞膜，并且是维生素D和许多类固醇激素（包括性激素）的前体。在真菌中，**麦角固醇**起着类似的作用。"
