                    "type": "text",
                    "value": "藻类是一类极其多样的光合生物，传统上被归类为水生植物。它们栖息于几乎所有的水生环境——从淡水湖泊和河流，到咸水海洋，以及潮湿的陆地环境，如树皮或岩石。它们构成了水生食物链的基础，是主要的有机物质和氧气生产者。它们的生态意义不可估量，进化作用至关重要，因为陆生植物的祖先应在藻类中寻找。本文将重点关注两大类藻类：绿藻和红藻。"
