                    "type": "text",
                    "value": "**分生组织**负责植物生长。顶端分生组织使植物得以长高。侧生分生组织，如维管形成层和木栓形成层，负责植物增粗，导致茎和根的次生构造。形成层的活动导致次生木质部的春材具有直径大、壁薄的导管，允许高效的水分运输。创伤组织由活的基本组织细胞去分化形成，用于再生损伤。"
